    public void testAppendFixedWidthPadLeft_NoPaddingNeeded() {
        StrBuilder sb = new StrBuilder();
        // obj="abcdef", width=3, padChar='0' -> "abc" (based on the logic str.getChars(strLen / width, strLen, buffer, size))
        // Note: The implementation provided has a specific logic: if strLen >= width, 
        // it does str.getChars(strLen / width, strLen, buffer, size);
        // If strLen=6, width=3, strLen/width=2. It takes chars from index 2 to 6.
        sb.appendFixedWidthPadLeft("abcdef", 3, '0');
        assertEquals("def", sb.toString());
    }












