public class StrBuilder_appendFixedWidthPadLeft_TriageGen2Test {







    @Test
    public void testAppendFixedWidthPadLeft_WidthZeroOrNegative() {
        StrBuilder sb = new StrBuilder("initial");
        // width <= 0 should do nothing
        sb.appendFixedWidthPadLeft("test", 0, '0');
        assertEquals("initial", sb.toString());

        sb.appendFixedWidthPadLeft("test", -1, '0');
        assertEquals("initial", sb.toString());
    }








